        /// <br/>            "warehouseCode": "central-warehouse-oslo-01"
        /// <br/>            "pickUpWarehouseCode": "STORE-OSLO-01"
        /// <br/>        }
        /// <br/>    ]
        /// <br/>            
        /// <br/>Example - Shipment with free shipping discount:
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddShipments
        /// <br/>    [
        /// <br/>        {
