        /// <summary>
        /// Add discount to cart
        /// </summary>
        /// <remarks>
        /// Add a discount to the cart. Use discountType to specify whether it applies to the order, specific line items, or other scenarios.
        /// <br/>            
        /// <br/>Note: Discounts are usually applied automatically to a cart - either by Omnium's promotions engine when adding items,
        /// <br/>when adding a coupon code, or when adding a customer to the cart and items are recalculated.
        /// <br/>If you are unsure whether you should use this endpoint or not, you probably shouldn't😵‍💫
        /// <br/>            
        /// <br/>Example - 20% order-level discount:
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddDiscount
        /// <br/>    {
        /// <br/>        "discountType": "Order",
        /// <br/>        "discountName": "Summer sale 20%",
        /// <br/>        "discountValue": 20,
        /// <br/>        "rewardType": "Percentage"
        /// <br/>    }
        /// <br/>            
        /// <br/>Example - Fixed amount discount (100 NOK off):
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddDiscount
        /// <br/>    {
        /// <br/>        "discountType": "Order",
        /// <br/>        "discountName": "100 NOK rabatt",
        /// <br/>        "discountValue": 100,
        /// <br/>        "rewardType": "Money"
        /// <br/>    }
        /// <br/>            
        /// <br/>Example - Line item discount on specific SKUs:
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddDiscount
        /// <br/>    {
        /// <br/>        "discountType": "LineItem",
        /// <br/>        "discountName": "50% on selected items",
        /// <br/>        "discountValue": 50,
        /// <br/>        "rewardType": "Percentage",
        /// <br/>        "skuIds": ["SKU-001", "SKU-002"]
        /// <br/>    }
        /// <br/>            
        /// <br/>Example - 3 for 2 promotion:
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddDiscount
        /// <br/>    {
        /// <br/>        "discountType": "LineItem",
        /// <br/>        "discountName": "3 for 2",
        /// <br/>        "rewardType": "MultiBuys",
        /// <br/>        "skuIds": ["SKU-001", "SKU-002", "SKU-003"],
        /// <br/>        "promotionMultiBuyReward": {
        /// <br/>            "requiredBuyAmount": 2,
        /// <br/>            "numberOfDiscountedItems": 1,
        /// <br/>            "percentage": 100
        /// <br/>        }
        /// <br/>    }
        /// </remarks>
        /// <param name="cartId">Cart ID</param>
        /// <param name="body">Discount to add to cart</param>
        /// <returns>Discount added and updated cart is returned</returns>
        /// <exception cref="OmniumApiException">A server side error occurred.</exception>
    
        System.Threading.Tasks.Task<SwaggerResponse<OmniumCart>?> CartAddDiscountAsync(string? cartId, OmniumDiscount? body);

