        /// <br/>        "paymentMethodName": "Vipps",
        /// <br/>        "transactionId": "xyz789",
        /// <br/>        "amount": 100.0,
        /// <br/>        "comment": "Refund for damaged item",
        /// <br/>        "reason": "Damaged item",
        /// <br/>        "storeId": "STORE-1",
        /// <br/>        "lineItemIds": [ "lineItem-1" ]
        /// <br/>    }
        /// </remarks>
        /// <param name="orderId">The ID of the order to credit. (Required)</param>
        /// <param name="body">The credit request. PaymentMethodName and TransactionId are required.</param>
