        /// <br/>            
        /// <br/>    POST /api/PrivateCustomers/AddComment
        /// <br/>    {
        /// <br/>       "CustomerId": "customer@example.com",
        /// <br/>       "CommentText": "Customer requested a callback regarding their recent order.",
        /// <br/>       "CreatedBy": "CRM System"
        /// <br/>    }
        /// <br/>            
        /// <br/>Sample request for adding a comment with email notification:
        /// <br/>            
        /// <br/>    POST /api/PrivateCustomers/AddComment
        /// <br/>    {
        /// <br/>       "CustomerId": "customer@example.com",
        /// <br/>       "CommentText": "Thank you for contacting us. We have received your inquiry and will respond shortly.",
        /// <br/>       "SendEmail": true,
        /// <br/>       "EmailSubject": "Inquiry Received",
        /// <br/>       "EmailTo": "customer@example.com",
        /// <br/>       "EmailFrom": "support@yourcompany.com",
        /// <br/>       "SenderName": "Customer Support"
        /// <br/>    }
        /// <br/>            
        /// <br/>Sample request for adding a comment with SMS notification:
        /// <br/>            
        /// <br/>    POST /api/PrivateCustomers/AddComment
        /// <br/>    {
        /// <br/>       "CustomerId": "customer@example.com",
        /// <br/>       "CommentText": "Your order has been shipped and will arrive within 2-3 business days.",
        /// <br/>       "SendSms": true,
        /// <br/>       "SmsPhoneNumber": "+4712345678"
        /// <br/>    }
        /// <br/>            
        /// <br/>Notes:
        /// <br/>- CreatedBy defaults to the current API user's username if not specified.
        /// <br/>- EmailTo, EmailFrom, SenderName, and SmsPhoneNumber will fall back to the store's (or global) default settings in Omnium if not specified.
        /// <br/>- EmailTo falls back to the customer's email. SmsPhoneNumber falls back to the customer's phone.
        /// </remarks>
        /// <param name="body">The comment request containing customer ID, comment text, and notification settings</param>
        /// <returns>Comment added successfully</returns>
        /// <exception cref="OmniumApiException">A server side error occurred.</exception>
    
        System.Threading.Tasks.Task<SwaggerResponse?> PrivateCustomersAddCommentAsync(OmniumCustomerCommentRequest? body);

