        /// <br/>           { "key": "CreateReturnLabel", "value": "true" }
        /// <br/>       ]
        /// <br/>    }
        /// <br/>            
        /// <br/>Example 1: Exchange with same value
        /// <br/>Customer returns product A (100 NOK) and gets product B (also 100 NOK). In this case, the return was done in physical store, so we'll also update shippingMethodName to "PickUpInStore" and set the order type for the exchange order to POS
        /// <br/>            
        /// <br/>    {
        /// <br/>       "returns": [
        /// <br/>           {
        /// <br/>               "lineItemId": "1",
        /// <br/>               "returnQuantity": 1,
        /// <br/>               "returnReason": "Too small!",
        /// <br/>               "returnType": "ProductWrongSize",
        /// <br/>               "isStockUpdated": true
        /// <br/>           }
        /// <br/>       ],
        /// <br/>       "storeId": "epic_webshop_no",
        /// <br/>       "userId": "permagne@omnium.no",
        /// <br/>       "creditPayment": true,
        /// <br/>       "omniumExchangeOrderOptions": {
        /// <br/>           "exchangeOrderLines": [
        /// <br/>               {
        /// <br/>                   "lineItemId": "1",
        /// <br/>                   "code": "076331601706",
        /// <br/>                   "placedPrice": 100,
        /// <br/>                   "quantity": 1
        /// <br/>               }
        /// <br/>           ],
        /// <br/>           "orderType": "POS",
        /// <br/>           "shippingMethodName": "PickUpInStore"
        /// <br/>       }
        /// <br/>    }
        /// <br/>            
        /// <br/>Example 2: Exchange with higher value
        /// <br/>Customer returns product A (100 NOK) and buys product B (150 NOK)
        /// <br/>            
        /// <br/>    {
        /// <br/>       "returns": [
        /// <br/>           {
        /// <br/>               "lineItemId": "1",
        /// <br/>               "returnQuantity": 1,
        /// <br/>               "returnReason": "Wrong product",
        /// <br/>               "returnType": "ProductWrongItem",
        /// <br/>               "isStockUpdated": true
        /// <br/>           }
        /// <br/>       ],
        /// <br/>       "storeId": "epic_webshop_no",
        /// <br/>       "userId": "permagne@omnium.no",
        /// <br/>       "creditPayment": true,
        /// <br/>       "omniumExchangeOrderOptions": {
        /// <br/>           "exchangeOrderLines": [
        /// <br/>               {
        /// <br/>                   "lineItemId": "1",
        /// <br/>                   "code": "076331601707",
        /// <br/>                   "placedPrice": 150,
        /// <br/>                   "quantity": 1
        /// <br/>               }
        /// <br/>           ],
        /// <br/>           "additionalPayments": [
        /// <br/>               {
        /// <br/>                   "amount": 50,
        /// <br/>                   "paymentMethodName" : "PaidInStore",
        /// <br/>                   "status": "Processed",
        /// <br/>                   "transactionId": "be5422f4-25d7-47fc-a664-61590266c7fa",
        /// <br/>                   "transactionType": "Sale"
        /// <br/>               }
        /// <br/>           ]
        /// <br/>       }
        /// <br/>    }
        /// <br/>            
        /// <br/>Example 3: Exchange with lower value
        /// <br/>Customer returns product A (100 NOK) and gets product B (90 NOK)
        /// <br/>            
        /// <br/>    {
        /// <br/>       "returns": [
        /// <br/>           {
        /// <br/>               "lineItemId": "1",
        /// <br/>               "returnQuantity": 1,
        /// <br/>               "returnReason": "Preferred another product",
        /// <br/>               "returnType": "ChangedMind",
        /// <br/>               "isStockUpdated": true
        /// <br/>           }
        /// <br/>       ],
        /// <br/>       "storeId": "epic_webshop_no",
        /// <br/>       "userId": "permagne@omnium.no",
        /// <br/>       "creditPayment": true,
        /// <br/>       "omniumExchangeOrderOptions": {
        /// <br/>           "exchangeOrderLines": [
        /// <br/>               {
        /// <br/>                   "lineItemId": "1",
        /// <br/>                   "code": "076331601708",
        /// <br/>                   "placedPrice": 90,
        /// <br/>                   "quantity": 1
        /// <br/>               }
        /// <br/>           ]
        /// <br/>       }
        /// <br/>    }
        /// <br/>            
        /// <br/>Example 4: Exchange that must be shipped from the warehouse
        /// <br/>Customer returns product A and gets product B which is NOT handed over in store but shipped from the warehouse.
        /// <br/>Set "shipmentOrderStatus" to "New" so the exchange order's shipment enters the normal warehouse fulfilment flow
        /// <br/>(awaiting inventory → picked → sent). When omitted the shipment inherits the exchange order's "orderStatus"
        /// <br/>(so a "New" exchange order gets a "New" shipment); if neither is set it defaults to "Completed" (already fulfilled, e.g. in-store pickup).
        /// <br/>            
        /// <br/>    {
        /// <br/>       "returns": [
        /// <br/>           {
        /// <br/>               "lineItemId": "1",
        /// <br/>               "returnQuantity": 1,
        /// <br/>               "returnReason": "Too small!",
        /// <br/>               "returnType": "ProductWrongSize",
        /// <br/>               "isStockUpdated": true
        /// <br/>           }
        /// <br/>       ],
        /// <br/>       "storeId": "epic_webshop_no",
        /// <br/>       "userId": "permagne@omnium.no",
        /// <br/>       "creditPayment": true,
        /// <br/>       "omniumExchangeOrderOptions": {
        /// <br/>           "exchangeOrderLines": [
        /// <br/>               {
        /// <br/>                   "lineItemId": "1",
        /// <br/>                   "code": "076331601709",
        /// <br/>                   "placedPrice": 100,
        /// <br/>                   "quantity": 1
        /// <br/>               }
        /// <br/>           ],
        /// <br/>           "shippingMethodName": "Bring",
        /// <br/>           "shipmentOrderStatus": "New"
        /// <br/>       }
        /// <br/>    }
        /// </remarks>
        /// <param name="orderId">The ID of the order</param>
        /// <param name="body">List of items to return. StoreId for return and userId</param>
