        /// <summary>
        /// Add payments to existing cart
        /// </summary>
        /// <remarks>
        /// Register payment transaction(s) from your payment provider on the cart.
        /// <br/>            
        /// <br/>The transactionId is typically provided by the payment provider and is often a GUID.
        /// <br/>This ID ties together related transactions - the same transactionId is for instance used for
        /// <br/>authorization, capture, and credit operations on the same payment.
        /// <br/>            
        /// <br/>For e-commerce orders: Use transactionType "Authorization" - Omnium workflows handle Capture/Credit/Void automatically.
        /// <br/>            
        /// <br/>For POS: Use transactionType "Sale" since payment is captured immediately.
        /// <br/>            
        /// <br/>Example - E-commerce payment (Klarna):
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddPayments
        /// <br/>    [
        /// <br/>        {
        /// <br/>            "amount": 999.00,
        /// <br/>            "paymentMethodName": "Klarna",
        /// <br/>            "transactionId": "klarna-order-abc123",
        /// <br/>            "transactionType": "Authorization",
        /// <br/>            "status": "Processed"
        /// <br/>        }
        /// <br/>    ]
        /// <br/>            
        /// <br/>Example - POS sale:
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddPayments
        /// <br/>    [
        /// <br/>        {
        /// <br/>            "amount": 599.00,
        /// <br/>            "paymentMethodName": "Card",
        /// <br/>            "transactionId": "terminal-tx-12345",
        /// <br/>            "transactionType": "Sale",
        /// <br/>            "status": "Processed"
        /// <br/>        }
        /// <br/>    ]
        /// <br/>            
        /// <br/>Example - Split payment (Gift card + Vipps):
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddPayments
        /// <br/>    [
        /// <br/>        {
        /// <br/>            "amount": 200.00,
        /// <br/>            "paymentMethodName": "GiftCard",
        /// <br/>            "transactionId": "GC-ABC123",
        /// <br/>            "transactionType": "Authorization",
        /// <br/>            "status": "Processed"
        /// <br/>        },
        /// <br/>        {
        /// <br/>            "amount": 799.00,
        /// <br/>            "paymentMethodName": "Vipps",
        /// <br/>            "transactionId": "vipps-order-xyz",
        /// <br/>            "transactionType": "Authorization",
        /// <br/>            "status": "Processed"
        /// <br/>        }
        /// <br/>    ]
        /// </remarks>
        /// <param name="cartId">ID of existing cart. (Required)</param>
