        /// <br/>        "discountName": "Summer sale 20%",
        /// <br/>        "discountValue": 20,
        /// <br/>        "rewardType": "Percentage"
        /// <br/>    }
        /// <br/>            
        /// <br/>Example - Fixed amount discount (100 NOK off):
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddDiscount
        /// <br/>    {
        /// <br/>        "discountType": "Order",
        /// <br/>        "discountName": "100 NOK rabatt",
        /// <br/>        "discountValue": 100,
        /// <br/>        "rewardType": "Money"
        /// <br/>    }
        /// <br/>            
        /// <br/>Example - Line item discount on specific SKUs:
        /// <br/>            
        /// <br/>    PUT /api/carts/{cartId}/AddDiscount
        /// <br/>    {
